   171→static void insert_char(char *pos, char c, uint8_t end)
   172→{
   173→	char tmp;
   174→
   175→	/* Echo back to console */
   176→	uart_poll_out(uart_console_dev, c);
   177→
   178→	if (end == 0U) {
   179→		*pos = c;
   180→		return;
   181→	}
   182→
   183→	tmp = *pos;
   184→	*(pos++) = c;
   185→
   186→	cursor_save();
   187→
   188→	while (end-- > 0) {
   189→		uart_poll_out(uart_console_dev, tmp);
   190→		c = *pos;
   191→		*(pos++) = tmp;
   192→		tmp = c;
   193→	}
   194→
   195→	/* Move cursor back to right place */
   196→	cursor_restore();
   197→}
