   222→enum {
   223→	ESC_ESC,
   224→	ESC_ANSI,
   225→	ESC_ANSI_FIRST,
   226→	ESC_ANSI_VAL,
   227→	ESC_ANSI_VAL_2,
   228→#ifdef CONFIG_UART_CONSOLE_MCUMGR
   229→	ESC_MCUMGR_PKT_1,
   230→	ESC_MCUMGR_PKT_2,
   231→	ESC_MCUMGR_FRAG_1,
   232→	ESC_MCUMGR_FRAG_2,
   233→#endif
   234→};
