   126→struct apbuart_dev_cfg {
   127→	struct apbuart_regs *regs;
   128→	int interrupt;
   129→};
   130→
   131→struct apbuart_dev_data {
   132→	int usefifo;
   133→#ifdef CONFIG_UART_INTERRUPT_DRIVEN
   134→	uart_irq_callback_user_data_t cb;
   135→	void *cb_data;
   136→#endif
   137→};
