   451→			return 1;
   452→		}
   453→	} else {
   454→		if ((ctrl & APBUART_CTRL_TI) && (status & APBUART_STATUS_TE)) {
   455→			return 1;
   456→		}
   457→	}
   458→
   459→	return 0;
   460→}
